# Now try collect with the targets
if targets and len(targets) > 0:
    try:
        result = await rlm.collect(targets, timeout_ms=1000)
        print("Collect result:", result)
    except Exception as e:
        print(f"Collect error: {e}")
else:
    print("No subagents")

